import React from 'react';

/** A formula with its digits as subscripts: "Li2CO3" -> Li<sub>2</sub>CO<sub>3</sub>. Plain text in, nodes out. */
export default function ChemicalFormula({ formula }) {
  // Only the formula itself: a trailing " (R-3c)" or " #2" keeps its digits.
  const [, head, tail] = /^([\s\S]*?)(\s[#(][\s\S]*)?$/.exec(String(formula || ''));
  const parts = head.split(/(\d+(?:\.\d+)?)/g).filter(Boolean);
  return <>{parts.map((part, index) => /^\d/.test(part) ? <sub key={index}>{part}</sub> : <React.Fragment key={index}>{part}</React.Fragment>)}{tail}</>;
}
